No bookmarks yet — paste a link above to save your first one.<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Bookmarks — prototype</title>
<style>
  :root { --bg:#f6f7f9; --card:#fff; --line:#e3e6ea; --ink:#1f2733; --muted:#6b7683; --accent:#2f6feb; }
  * { box-sizing:border-box; }
  body { margin:0; font-family:-apple-system,Segoe UI,Roboto,Helvetica,Arial,sans-serif;
         background:var(--bg); color:var(--ink); }
  header { padding:18px 20px; background:var(--card); border-bottom:1px solid var(--line); }
  header h1 { margin:0; font-size:19px; }
  main { max-width:720px; margin:0 auto; padding:20px; }
  .card { background:var(--card); border:1px solid var(--line); border-radius:12px; padding:18px; margin-bottom:18px; }
  label { display:block; font-size:13px; color:var(--muted); margin:12px 0 5px; }
  input[type=text], textarea, input[type=url] {
    width:100%; padding:10px 12px; border:1px solid var(--line); border-radius:8px; font-size:15px; font-family:inherit; }
  textarea { resize:vertical; min-height:60px; }
  .row { display:flex; gap:10px; }
  .row input { flex:1; }
  button { border:0; border-radius:8px; padding:10px 16px; font-size:15px; cursor:pointer; }
  .primary { background:var(--accent); color:#fff; }
  .ghost { background:#eef1f5; color:var(--ink); }
  .hint { font-size:12px; color:var(--muted); margin-top:6px; }
  .preview { display:flex; gap:12px; align-items:flex-start; margin-top:14px; padding:12px;
             background:#f2f6ff; border:1px solid #d5e2ff; border-radius:10px; }
  .preview .fav { width:34px; height:34px; border-radius:7px; background:var(--accent); color:#fff;
                  display:flex; align-items:center; justify-content:center; font-weight:700; flex:0 0 auto; }
  .preview .t { font-weight:600; }
  .preview .d { font-size:13px; color:var(--muted); margin-top:2px; }
  .tags { display:flex; flex-wrap:wrap; gap:6px; margin-top:8px; }
  .tag { background:#eef1f5; border-radius:999px; padding:4px 10px; font-size:13px; display:flex; gap:6px; align-items:center; }
  .tag button { background:none; padding:0; color:var(--muted); font-size:14px; line-height:1; }
  .list h2 { font-size:14px; color:var(--muted); text-transform:uppercase; letter-spacing:.04em; margin:0 0 12px; }
  .item { display:flex; gap:12px; padding:12px 0; border-bottom:1px solid var(--line); }
  .item:last-child { border-bottom:0; }
  .item .fav { width:30px; height:30px; border-radius:7px; background:#dbe4f3; color:var(--accent);
               display:flex; align-items:center; justify-content:center; font-weight:700; flex:0 0 auto; }
  .item .t { font-weight:600; }
  .item .u { font-size:12px; color:var(--muted); word-break:break-all; }
  .item .note { font-size:13px; margin-top:4px; }
  .item .tags { margin-top:6px; }
  .empty { color:var(--muted); text-align:center; padding:26px 0; }
  .navbtn { background:#eef1f5; color:var(--ink); }
  .navbtn.active { background:var(--accent); color:#fff; }
  .item .actions { display:flex; gap:8px; margin-top:8px; }
  .item .actions button { background:#eef1f5; color:var(--ink); font-size:13px; padding:5px 10px; }
  .item .actions button.on { background:#ffedb3; color:#7a5a00; }
  .laterbadge { font-size:12px; color:#a06d00; background:#fff3cf; border-radius:999px; padding:2px 8px; margin-left:8px; }
  .toast { position:fixed; left:50%; bottom:24px; transform:translateX(-50%); background:#1f2733; color:#fff;
           padding:10px 18px; border-radius:999px; font-size:14px; opacity:0; transition:opacity .2s; pointer-events:none; }
  .toast.show { opacity:1; }
  @media (max-width:520px){ .row{ flex-direction:column; } }
</style>
</head>
<body>
<header><h1>📑 My Bookmarks</h1></header>
<nav id="nav" style="max-width:720px;margin:0 auto;padding:14px 20px 0;display:flex;gap:8px;">
  <button class="navbtn" data-view="all">All</button>
  <button class="navbtn" data-view="later">Read later</button>
  <button class="navbtn" data-view="archive">Archive</button>
</nav>
<main>
  <div class="card">
    <label for="url">Paste a link to save</label>
    <div class="row">
      <input type="url" id="url" placeholder="https://…" autocomplete="off" />
      <button class="ghost" id="fetchBtn">Fetch details</button>
    </div>
    <div class="hint">Paste a link and its title &amp; description are filled in automatically.</div>

    <div id="dupWarn" style="display:none; margin-top:14px; padding:12px; background:#fff3cf; border:1px solid #f0d98a; border-radius:10px;">
      <div id="dupMsg" style="margin-bottom:10px;"></div>
      <button class="primary" id="dupEditBtn">Edit the saved bookmark</button>
      <button class="ghost" id="dupCancelBtn">Cancel</button>
    </div>

    <div id="editingBanner" style="display:none; margin-top:14px; font-size:13px; color:#7a5a00; background:#fff3cf; border-radius:8px; padding:8px 12px;">
      Editing an existing bookmark — your changes will update it in place.
    </div>

    <div id="preview" style="display:none;">
      <div class="preview">
        <div class="fav" id="pvFav">?</div>
        <div>
          <div class="t" id="pvTitle"></div>
          <div class="d" id="pvDesc"></div>
        </div>
      </div>
      <label for="titleEdit">Title</label>
      <input type="text" id="titleEdit" />
      <label for="note">Short note (optional)</label>
      <textarea id="note" placeholder="Why is this worth keeping?"></textarea>
      <label for="tagInput">Tags (optional) — type a tag and press Enter</label>
      <input type="text" id="tagInput" placeholder="e.g. design, reference" />
      <div class="tags" id="tagList"></div>
      <div style="margin-top:16px; display:flex; gap:10px;">
        <button class="primary" id="saveBtn">Save bookmark</button>
        <button class="ghost" id="cancelBtn">Cancel</button>
      </div>
    </div>
  </div>

  <div class="card">
    <label for="search">Find a bookmark</label>
    <input type="text" id="search" placeholder="Search title, note, link or tag…" autocomplete="off" />
    <div class="tags" id="filterTags" style="margin-top:10px;"></div>
    <div class="hint" id="activeFilter" style="display:none;"></div>
  </div>

  <div class="card list">
    <h2 id="listHeading">Saved</h2>
    <div id="items"></div>
  </div>
</main>
<div class="toast" id="toast"></div>

<script>
// --- prototype-only mock of "automatic detail fetching" ---
const MOCK = {
  "figma.com": {title:"Figma: The Collaborative Interface Design Tool", desc:"Design, prototype, and gather feedback all in one place."},
  "developer.mozilla.org": {title:"MDN Web Docs", desc:"Resources for developers, by developers."},
  "nytimes.com": {title:"The New York Times — Breaking News, US & World", desc:"Live news, investigations, opinion, photos and video."},
  "github.com": {title:"GitHub · Build and ship software", desc:"The complete developer platform to build, scale, and deliver software."},
  "stripe.com": {title:"Stripe | Payment Processing Platform", desc:"Online payment processing for internet businesses."}
};
function domainOf(u){ try { return new URL(u).hostname.replace(/^www\./,''); } catch { return ""; } }
function lookup(u){
  const d = domainOf(u);
  if (MOCK[d]) return MOCK[d];
  if (!d) return null;
  const name = d.split(".")[0];
  return { title: name.charAt(0).toUpperCase()+name.slice(1) + " — " + d, desc: "Saved from " + d };
}

let pending = null;      // {url, title, desc, tags:[]}
let editingId = null;    // id of bookmark being edited (duplicate resolution / edit)
let items = [
  {id:1, url:"https://developer.mozilla.org/en-US/docs/Web/CSS/grid", title:"CSS Grid Layout — MDN", note:"Reference for the grid shorthand I keep forgetting.", tags:["reference","css"], later:false, archived:false},
